-- ============================================================
-- Human-readable booking reference (e.g. HB-7K4M2Q)
--
-- The cuid primary key is unusable at a front desk or over the phone, so every
-- booking also gets a short reference. It is generated by the database, which
-- means seeds, manual inserts and the app all get one without extra code.
--
-- Safe to re-run: every statement is guarded.
-- ============================================================

BEGIN;

-- ------------------------------------------------------------
-- 1. Generator
--
-- Alphabet drops 0/O/1/I/L so a reference read aloud can't come back wrong.
-- 31^6 ≈ 887 million combinations; the loop retries on the rare collision so
-- the caller never sees a unique violation.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION generate_booking_ref() RETURNS text AS $$
DECLARE
  alphabet CONSTANT text := '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
  candidate text;
  i int;
BEGIN
  LOOP
    candidate := 'HB-';
    FOR i IN 1..6 LOOP
      candidate := candidate || substr(alphabet, floor(random() * length(alphabet))::int + 1, 1);
    END LOOP;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM "Booking" WHERE reference = candidate);
  END LOOP;
  RETURN candidate;
END;
$$ LANGUAGE plpgsql;

-- ------------------------------------------------------------
-- 2. Column, added nullable so existing rows survive the ALTER
-- ------------------------------------------------------------
ALTER TABLE "Booking" ADD COLUMN IF NOT EXISTS "reference" TEXT;

-- ------------------------------------------------------------
-- 3. Backfill anything created before this migration
-- ------------------------------------------------------------
UPDATE "Booking" SET "reference" = generate_booking_ref() WHERE "reference" IS NULL;

-- ------------------------------------------------------------
-- 4. Lock it down: unique, required, generated by default
-- ------------------------------------------------------------
CREATE UNIQUE INDEX IF NOT EXISTS "Booking_reference_key" ON "Booking"("reference");
ALTER TABLE "Booking" ALTER COLUMN "reference" SET DEFAULT generate_booking_ref();
ALTER TABLE "Booking" ALTER COLUMN "reference" SET NOT NULL;

COMMIT;
